 const r=await Reader.create(database,options),documents=r.all("bim_document");if(documents.length!==1)fail("one document required");const doc=documents[0]!,dc=await r.take(doc),schema=dc.text();dc.done();const pr=(await r.one("bim_project",doc.rowid))!,pc=await r.take(pr,2),projectValue=project.from(pc);pc.done();projectValue.phase_names=await readOrdered(r,"bim_phase_name",pr.rowid,text);const snapshot:ModelSnapshot={schema,project:projectValue};
 for(const[key,table,codec]of collections){const map:ObjectValue={};for(const[name,row]of await readNamed(r,table,doc.rowid)){const c=await r.take(row,4),value: any=codec===null?{}:codec.from(c);c.done();switch(key){
 case"wall_types":case"slab_types":case"roof_types":value.layers=await readOrdered(r,key==="wall_types"?"bim_wall_layer":key==="slab_types"?"bim_slab_layer":"bim_roof_layer",row.rowid,layer);break;
 case"column_types":case"beam_types":value.profile=await readProfile(r,row.rowid,key==="column_types"?0:1);break;
 case"sites":value.boundary=await readOrdered(r,"bim_site_boundary",row.rowid,point);break;
 case"walls":case"curtain_walls":value.axis=await readOwned(r,"bim_axis",row.rowid,key==="walls"?0:1,2,axis);value.top=await readOwned(r,"bim_top",row.rowid,key==="walls"?0:1,4,top);if(key==="curtain_walls")value.mullion=await readProfile(r,row.rowid,2);break;
 case"columns":case"stairs":value.top=await readOwned(r,"bim_top",row.rowid,key==="columns"?2:3,4,top);break;
 case"slabs":value.boundary=await readOrdered(r,"bim_slab_boundary",row.rowid,vertex);value.holes=[];for(const h of await r.group("bim_slab_hole",row.rowid)){const hc=await r.take(h,3);hc.done();value.holes.push(await readOrdered(r,"bim_slab_hole_vertex",h.rowid,vertex))}break;
 case"roofs":value.footprint=await readOrdered(r,"bim_roof_footprint",row.rowid,vertex);break;
 case"railings":value.path=await readOrdered(r,"bim_railing_path",row.rowid,point);value.profile=await readProfile(r,row.rowid,3);value.post_profile=await readProfile(r,row.rowid,4);{const b=await r.one("bim_baluster",row.rowid,1,false);if(b){const bc=await r.take(b,2),spacing=number.from(bc);bc.done();value.baluster={spacing,profile:await readProfile(r,b.rowid,5)}}}break;
 case"spaces":{const outline=await readOrdered(r,"bim_space_outline",row.rowid,vertex);if("Explicit"in value.boundary)value.boundary.Explicit.outline=outline;else if(outline.length)fail("outline on bounded space");break}
 case"properties":for(const[setName,setRow]of await readNamed(r,"bim_property_set",row.rowid)){const sc=await r.take(setRow,4);sc.done();const set:ObjectValue={};for(const[propertyName,propertyRow]of await readNamed(r,"bim_property_value",setRow.rowid)){const vc=await r.take(propertyRow,4);assign(set,propertyName,propertyFrom(vc));vc.done()}assign(value,setName,set)}break;
 }assign(map,name,value)}assign(snapshot as unknown as ObjectValue,key,map)}
 await r.finish();return snapshot;
}
